import { getSnapshot, model, onPatch } from '@pyreon/state-tree'

type Todo = { id: string; title: string; done: boolean }

const TodoList = model({ state: { todos: [] as Todo[] } })
  .views((self) => ({
    left: () => self.todos().filter((t) => !t.done).length,
  }))
  .actions((self) => ({
    add: (title: string) =>
      self.todos.update((xs) => [...xs, { id: String(xs.length + 1), title, done: false }]),
    toggle: (id: string) =>
      self.todos.update((xs) => xs.map((t) => (t.id === id ? { ...t, done: !t.done } : t))),
  }))

const list = TodoList.create()
onPatch(list, (patch) => console.log(patch))
list.add('Write docs')
list.toggle('1') // { op: 'replace', path: '/todos', value: [{ id: '1', …, done: true }] }
console.log(list.left(), getSnapshot(list))

