import { addMiddleware, applySnapshot, getSnapshot, model, onSnapshot } from '@pyreon/state-tree'

const Editor = model({ state: { text: '', fontSize: 14, readOnly: false } })
  .actions((self) => ({
    type: (t: string) => self.text.update((s) => s + t),
    zoom: (by: number) => self.fontSize.update((n) => n + by),
  }))

const doc = Editor.create()
const past = [getSnapshot(doc)]

// one snapshot per burst of changes (onSnapshot is microtask-coalesced)
onSnapshot(doc, (snap) => past.push(snap))

// middleware sees every action and can block it
addMiddleware(doc, (call, next) => (doc.readOnly() ? undefined : next(call)))

doc.type('Hello')
await Promise.resolve()
doc.zoom(2)
await Promise.resolve()

const undo = () => {
  if (past.length < 2) return
  past.pop() // the current state
  // the restored state is pushed back by onSnapshot on the next microtask
  applySnapshot(doc, past.pop()!)
}
undo()
await Promise.resolve()
console.log(doc.text(), doc.fontSize()) // 'Hello' 14
